  if (!page) {
    console.log("Could not find page 0:1");
    return;
  }

  function dumpText(node) {
    let result = "";
    if (node.type === "TEXT") {
      result += `[TEXT: ${node.name}] "${node.characters}"\n`;
    }
    if ("children" in node) {
      for (const child of node.children) {
        result += dumpText(child);
      }
    }
    return result;
  }

  console.log(dumpText(page));
