run();

const page = figma.getNodeById("0:1");
if (!page) {
  return "Page 0:1 not found";
}

function dumpText(node, depth = 0) {
  let lines = [];
  if (node.type === "TEXT") {
    lines.push(`${'  '.repeat(depth)}[${node.name}]: ${node.characters}`);
  } else if ("children" in node) {
    lines.push(`${'  '.repeat(depth)}<${node.type} name="${node.name}">`);
    for (const child of node.children) {
      lines.push(dumpText(child, depth + 1));
    }
    lines.push(`${'  '.repeat(depth)}</${node.type}>`);
  }
  return lines.filter(Boolean).join("\n");
}

return dumpText(page);

const pFoundations = figma.getNodeById("1:2");
const pComponents = figma.getNodeById("1:3");
const pMedia = figma.getNodeById("1:4");

function listChildren(node, depth = 0) {
  let lines = [];
  if (depth < 3) {
    lines.push(`${'  '.repeat(depth)}- [${node.type}] "${node.name}" (${node.id})`);
    if ("children" in node) {
      for (const child of node.children) {
        lines.push(listChildren(child, depth + 1));
      }
    }
  }
  return lines.filter(Boolean).join("\n");
}

return {
  foundations: pFoundations ? listChildren(pFoundations) : "not found",
  components: pComponents ? listChildren(pComponents) : "not found",
  media: pMedia ? listChildren(pMedia) : "not found"
};

const pMedia = figma.getNodeById("1:4");
if (!pMedia) return "Media page not found";

function findComponents(node) {
  let list = [];
  if (node.type === "COMPONENT" || node.type === "COMPONENT_SET") {
    list.push({ type: node.type, name: node.name, id: node.id });
  } else if ("children" in node) {
    for (const child of node.children) {
      list = list.concat(findComponents(child));
    }
  }
  return list;
}

const comps = findComponents(pMedia);
return comps.map(c => `${c.type}: ${c.name} (${c.id})`).join("\n");

const pWorkspace = figma.getNodeById("3:2");
if (!pWorkspace) return "Workspace page 3:2 not found";
return {
  name: pWorkspace.name,
  childrenCount: pWorkspace.children.length,
  children: pWorkspace.children.map(c => ({ id: c.id, name: c.name, type: c.type }))
};

const brandColorsFrame = figma.getNodeById("1:9");
const btn = figma.getNodeById("1:23");
const txtField = figma.getNodeById("1:26");

function inspectNode(node) {
  if (!node) return null;
  return {
    id: node.id,
    name: node.name,
    type: node.type,
    fills: node.fills,
    strokes: node.strokes,
    cornerRadius: node.cornerRadius,
    children: node.children ? node.children.map(inspectNode) : undefined
  };
}

return {
  brandColors: inspectNode(brandColorsFrame),
  button: inspectNode(btn),
  textField: inspectNode(txtField)
};

async function createWorkspace() {
  await Promise.all([
    figma.loadFontAsync({ family: "Inter", style: "Regular" }),
    figma.loadFontAsync({ family: "Inter", style: "Medium" }),
    figma.loadFontAsync({ family: "Inter", style: "Semi Bold" }),
    figma.loadFontAsync({ family: "Inter", style: "Bold" })
  ]);

  const workspacePage = figma.getNodeById("3:2");
  await figma.setCurrentPageAsync(workspacePage);

  // Clear any existing contents in workspace
  for (const child of workspacePage.children) {
    child.remove();
  }

  const frameNames = [
    "01_Home",
    "02_Products",
    "03_Product_Details",
    "04_Shopping_Cart",
    "05_Checkout_Address",
    "06_Checkout_Shipping",
    "07_Checkout_Payment"
  ];

  const frames = {};
  for (let i = 0; i < frameNames.length; i++) {
    const frame = figma.createFrame();
    frame.name = frameNames[i];
    frame.resize(1440, 3000); // We will adjust height or let auto-layout handle it if we want, or absolute layout with custom heights
    frame.x = i * 1600;
    frame.y = 0;
    frame.fills = [{ type: "SOLID", color: { r: 1, g: 1, b: 1 } }];
    workspacePage.appendChild(frame);
    frames[frameNames[i]] = frame;
  }

  return "Created 7 workspace frames successfully!";
}
return createWorkspace();

