async function wirePrototype() {
  const workspacePage = figma.getNodeById("3:2");
  if (!workspacePage) return "Workspace page not found";

  const f01 = workspacePage.findChild(n => n.name === "01_Home");
  const f02 = workspacePage.findChild(n => n.name === "02_Products");
  const f03 = workspacePage.findChild(n => n.name === "03_Product_Details");
  const f04 = workspacePage.findChild(n => n.name === "04_Shopping_Cart");
  const f05 = workspacePage.findChild(n => n.name === "05_Checkout_Address");
  const f06 = workspacePage.findChild(n => n.name === "06_Checkout_Shipping");
  const f07 = workspacePage.findChild(n => n.name === "07_Checkout_Payment");

  if (!f01 || !f02 || !f03 || !f04 || !f05 || !f06 || !f07) {
    return "One or more frames missing";
  }

  function addLink(node, destinationNode) {
    if (!node || !destinationNode) return;
    try {
      node.reactions = [
        {
          trigger: { type: "ON_CLICK" },
          actions: [
            {
              type: "NODE",
              destinationId: destinationNode.id,
              navigation: "NAVIGATE",
              transition: { type: "DISSOLVE", easing: { type: "EASE_IN_AND_OUT" }, duration: 0.3 },
              preserveScrollPosition: false
            }
          ]
        }
      ];
    } catch (e) {
      console.log("Error linking node:", node.name, e);
    }
  }

  // Header links across all frames:
  // Wordmark -> 01_Home
  // Cart icon -> 04_Shopping_Cart
  const allFrames = [f01, f02, f03, f04, f05, f06, f07];
  for (const f of allFrames) {
    const wm = f.findOne(n => n.name === "Wordmark");
    if (wm) addLink(wm, f01);
    const navHome = f.findOne(n => n.name === "Nav_Home");
    if (navHome) addLink(navHome, f01);
    const cartI = f.findOne(n => n.name === "Icon_Cart");
    if (cartI) addLink(cartI, f04);
  }

  // 1. 01_Home links:
  // - Hero Shop Now or Phones tile → 02_Products
  const heroBtn = f01.findOne(n => n.name === "Hero_Shop_Now_Button");
  if (heroBtn) addLink(heroBtn, f02);

  const phoneCat = f01.findOne(n => n.name === "Category_Tile_Phones");
  if (phoneCat) addLink(phoneCat, f02);

  // - Pomelo One 14 Pro Max card → 03_Product_Details
  const purpleCard = f01.findOne(n => n.name && n.name.includes("Pomelo One 14 Pro Max 128GB Deep Purple"));
  if (purpleCard) addLink(purpleCard, f03);

  // 2. 02_Products links:
  // - Pomelo One 14 Pro 512GB Gold card → 03_Product_Details
  const goldCard = f02.findOne(n => n.name && n.name.includes("Pomelo One 14 Pro 512GB Gold"));
  if (goldCard) addLink(goldCard, f03);

  // - Home (breadcrumb or nav) → 01_Home
  const bcHome = f02.findOne(n => n.type === "TEXT" && n.characters === "Home");
  if (bcHome) addLink(bcHome, f01);

  // 3. 03_Product_Details links:
  // - Add to Cart → 04_Shopping_Cart
  const addToCartBtn = f03.findOne(n => n.name === "Button_Add_to_Cart");
  if (addToCartBtn) addLink(addToCartBtn, f04);

  // - Breadcrumb Smartphones → 02_Products
  const bcSmartphones = f03.findOne(n => n.type === "TEXT" && n.characters === "Smartphones");
  if (bcSmartphones) addLink(bcSmartphones, f02);

  // 4. 04_Shopping_Cart links:
  // - Checkout → 05_Checkout_Address
  const checkoutBtn = f04.findOne(n => n.name === "Button_Checkout");
  if (checkoutBtn) addLink(checkoutBtn, f05);

  // - Product name → 03_Product_Details
  const cartProdName = f04.findOne(n => n.name === "Product_Name" && n.characters.includes("Pomelo One 14 Pro Max"));
  if (cartProdName) addLink(cartProdName, f03);

  // 5. 05_Checkout_Address links:
  // - Next → 06_Checkout_Shipping
  // - Back → 04_Shopping_Cart
  const nextBtn05 = f05.findOne(n => n.name === "Button_Next");
  if (nextBtn05) addLink(nextBtn05, f06);

  const backBtn05 = f05.findOne(n => n.name === "Button_Back");
  if (backBtn05) addLink(backBtn05, f04);

  // 6. 06_Checkout_Shipping links:
  // - Next → 07_Checkout_Payment
  // - Back → 05_Checkout_Address
  const nextBtn06 = f06.findOne(n => n.name === "Button_Next");
  if (nextBtn06) addLink(nextBtn06, f07);

  const backBtn06 = f06.findOne(n => n.name === "Button_Back");
  if (backBtn06) addLink(backBtn06, f05);

  // 7. 07_Checkout_Payment links:
  // - Back → 06_Checkout_Shipping
  const backBtn07 = f07.findOne(n => n.name === "Button_Back");
  if (backBtn07) addLink(backBtn07, f06);

  return "All prototype interactions wired successfully!";
}
return wirePrototype();
